    private const int BlockSize = 32;

    private static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        double[] matrix = new double[(long)n * n];

        for (int i = 0; i < n; i++)
        {
            int offset = i * n;
            for (int j = 0; j < n; j++)
            {
                int s = i + j;
                int denominator = s * (s + 1) / 2 + i + 1;
                matrix[offset + j] = 1.0 / denominator;
            }
        }

        double[] u = new double[n];
        double[] v = new double[n];

        for (int i = 0; i < n; i++)
            v[i] = 1.0;

        for (int iteration = 0; iteration < PowerIterations; iteration++)
        {
            for (int i = 0; i < n; i++)
            {
                int offset = i * n;
                double sum = 0.0;

                for (int j = 0; j < n; j++)
                    sum += matrix[offset + j] * v[j];

                u[i] = sum;
            }

            Array.Clear(v, 0, n);

            for (int rowBlock = 0; rowBlock < n; rowBlock += BlockSize)
            {
                int rowEnd = Math.Min(rowBlock + BlockSize, n);

                for (int columnBlock = 0; columnBlock < n; columnBlock += BlockSize)
                {
                    int columnEnd = Math.Min(columnBlock + BlockSize, n);

                    for (int i = rowBlock; i < rowEnd; i++)
                    {
                        double value = u[i];
                        int offset = i * n + columnBlock;

                        for (int j = columnBlock; j < columnEnd; j++)
                            v[j] += matrix[offset + (j - columnBlock)] * value;
                    }
                }
            }
        }

        double vBv = 0.0;
        double vv = 0.0;

        for (int i = 0; i < n; i++)
