static class Program
{
    private static TreeNode MakeTree(int depth)
    {
        if (depth == 0)
            return new TreeNode();

        return new TreeNode(
            MakeTree(depth - 1),
            MakeTree(depth - 1));
    }

    private static long NodeCount(int depth)
    {
        return (1L << (depth + 1)) - 1;
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        int stretchDepth = n + 1;
        TreeNode stretchTree = MakeTree(stretchDepth);
        Console.WriteLine(
            $"stretch tree of depth {stretchDepth}\t check: {NodeCount(stretchDepth)}");
        GC.KeepAlive(stretchTree);
        stretchTree = null;

        TreeNode longLivedTree = MakeTree(n);

        for (int depth = 4; depth <= n; depth += 2)
        {
            long treeCount = 1L << (n - depth + 4);

            for (long i = 0; i < treeCount; i++)
            {
                TreeNode shortLivedTree = MakeTree(depth);
                GC.KeepAlive(shortLivedTree);
            }

            long checksum = treeCount * NodeCount(depth);
            Console.WriteLine(
                $"{treeCount}\t trees of depth {depth}\t check: {checksum}");
        }

        Console.WriteLine(
            $"long lived tree of depth {n}\t check: {NodeCount(n)}");
        GC.KeepAlive(longLivedTree);
    }
}
