        {
            int offset = y * rowBytes;
            double ci = imag[y];

            int bits = 0;
            int bitCount = 0;
            int outputIndex = offset;

            for (int x = 0; x < n; x++)
            {
                double cr = real[x];
                double zr = 0.0;
                double zi = 0.0;
                bool inside = true;

                for (int i = 0; i < 50; i++)
                {
                    double zr2 = zr * zr;
