using System;
using System.Numerics;
using System.Text;

public static class Program
{
    private static BigInteger IntegerSqrt(BigInteger value)
    {
        if (value < 0)
            throw new ArgumentOutOfRangeException(nameof(value));
        if (value < 2)
            return value;

        int bitLength = 0;
        BigInteger temp = value;
        while (temp > 0)
        {
            temp >>= 1;
            bitLength++;
        }

        BigInteger x = BigInteger.One << ((bitLength + 1) / 2);

        while (true)
        {
            BigInteger next = (x + value / x) >> 1;
            if (next >= x)
                return x;
            x = next;
        }
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        const int guardDigits = 40;
        int precision = n + guardDigits;
        BigInteger scale = BigInteger.Pow(10, precision);

        BigInteger c = 640320;
        BigInteger cCubed = c * c * c;

        BigInteger sum = 13591409 * scale;
        BigInteger term = scale;

        int terms = n / 14 + 20;

        for (int k = 1; k <= terms; k++)
        {
            BigInteger kk = k;
            BigInteger numerator =
                (6 * kk - 5) *
                (6 * kk - 4) *
                (6 * kk - 3) *
                (6 * kk - 2) *
                (6 * kk - 1) *
                (6 * kk);

            BigInteger denominator =
                kk * kk * kk *
                (3 * kk - 2) *
                (3 * kk - 1) *
                (3 * kk) *
                cCubed;

            term = term * numerator / denominator;

            BigInteger coefficient = 13591409 + 545140134 * kk;
            BigInteger contribution = term * coefficient;

            if ((k & 1) != 0)
                sum -= contribution;
            else
                sum += contribution;

            if (term.IsZero)
                break;
        }

        BigInteger sqrtArgument = 10005 * scale * scale;
        BigInteger sqrt = IntegerSqrt(sqrtArgument);

        BigInteger piScaled = (426880 * sqrt * scale) / sum;
        string pi = piScaled.ToString();

        int requiredLength = n + 1;
        if (pi.Length < requiredLength)
            pi = pi.PadLeft(requiredLength, '0');

        StringBuilder output = new StringBuilder();

        for (int start = 0; start < n; start += 10)
        {
            int count = Math.Min(10, n - start);
            output.Append(pi, start, count);
            output.Append("\t:");
            output.Append(start + count);
            output.Append('\n');
        }

        Console.Write(output.ToString());
    }
}
