                }
            }

            if (data[i] != (byte)'\n')
                strippedChars[strippedLength++] = (char)data[i];

            i++;
        }

        string sequence = new string(strippedChars, 0, strippedLength);

        string[] patterns =
        {
            "agggtaaa|tttaccct",
