            "agggta[cgt]a|t[acg]taccct",
            "agggtaa[cgt]|[acg]ttaccct"
        };

        var counts = new int[patterns.Length];
        for (int p = 0; p < patterns.Length; p++)
        {
            var regex = new Regex(patterns[p], RegexOptions.Compiled | RegexOptions.CultureInvariant);
            Match match = regex.Match(sequence);

            while (match.Success)
            {
                counts[p]++;
                match = match.NextMatch();
            }
        }

        string substituted = sequence;
        substituted = Regex.Replace(substituted, "tHa[Nt]", "<4>");
        substituted = Regex.Replace(substituted, "aND|caN|Ha[DS]|WaS", "<3>");
        substituted = Regex.Replace(substituted, "a[NSt]|BY", "<2>");
        substituted = Regex.Replace(substituted, "<[^>]*>", "|");
        substituted = Regex.Replace(substituted, "\\|[^|][^|]*\\|", "-");

        var output = new StringBuilder();

        for (int p = 0; p < patterns.Length; p++)
            output.Append(patterns[p]).Append(' ').Append(counts[p]).Append('\n');

        output.Append('\n');
        output.Append(originalLength).Append('\n');
        output.Append(sequence.Length).Append('\n');
        output.Append(substituted.Length).Append('\n');

        Console.Write(output.ToString());
    }
