            if (line.Length > 0 && line[0] == '>')
            {
                if (header != null)
                    WriteRecord(writer, header, sequence, lineLengths);

                header = line;
                sequence.Clear();
                lineLengths.Clear();
            }
            else if (header != null)
            {
                int count = 0;
                for (int i = 0; i < line.Length; i++)
                {
                    char c = line[i];
                    if (!char.IsWhiteSpace(c))
                    {
                        sequence.Append(c);
                        count++;
                    }
                }

                lineLengths.Add(count);
            }
        }

        if (header != null)
            WriteRecord(writer, header, sequence, lineLengths);
    }

    private static void WriteRecord(
        StreamWriter writer,
        string header,
        StringBuilder sequence,
        List<int> lineLengths)
    {
        writer.Write(header);
        writer.Write('\n');

        string source = sequence.ToString();
        char[] reverseComplement = new char[source.Length];

        for (int i = 0; i < source.Length; i++)
            reverseComplement[i] = Complement(source[source.Length - 1 - i]);

        int position = 0;
        for (int i = 0; i < lineLengths.Count; i++)
        {
            int length = lineLengths[i];
            if (length > 0)
                writer.Write(reverseComplement, position, length);

            writer.Write('\n');
            position += length;
        }

        if (position < reverseComplement.Length)
        {
            writer.Write(reverseComplement, position, reverseComplement.Length - position);
            writer.Write('\n');
        }
    }

